/* Side-panel chrome — white surface, header / scrolling body / pinned footer.
 * Outer width/borders/radius come from the consumer's className. */
.side-panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
  background: var(--card);

  overflow: hidden;
}

.side-panel-header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  padding: var(--space-4);
}
.side-panel-title {
  margin: 0;
  font-family: var(--font-family-display);
  font-size: var(--font-xl);
  font-weight: var(--font-weight-regular);
  line-height: var(--leading-tight);
}

/* Controls in the header. `margin-inline-start: auto` puts them at the far end when there is no
   close button beside them, which is the common case (a collapse toggle alone). */
.side-panel-actions {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  margin-inline-start: auto;
}

.side-panel-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: 0 var(--space-4) var(--space-4);
  font-size: var(--font-base);
  line-height: var(--leading-normal);
}

.side-panel-footer {
  flex-shrink: 0;
  display: flex;
  justify-content: flex-end;
  gap: var(--space-2);
  padding: var(--space-4);
  border-block-start: 1px solid var(--border);
}

/* A panel that is a wide-screen affordance drops out below its width rather
 * than wrapping under the content, where it is a jump list pointing at what the
 * reader already passed. The numbers are repeated because a media query cannot
 * read a custom property; the linter holds them to the breakpoint scale. */
@media (max-width: 30rem) {
  .side-panel[data-hide-below='sm'],
  /* And the region that holds it. <Page> renders `<aside class="page-aside">`
     around whatever it is given; leaving that in the flow around a hidden panel
     keeps a zero-height column on the page, which is what the audit measures
     and reports (2026-08-26). Hiding the panel without its region is half a
     fix. */
  .page-aside:has(> .side-panel[data-hide-below='sm']) { display: none; }
}
@media (max-width: 48rem) {
  .side-panel[data-hide-below='md'],
  .page-aside:has(> .side-panel[data-hide-below='md']) { display: none; }
}

import './SidePanel.css'
import type { ReactNode } from 'react'
import { useTranslation } from 'react-i18next'
import { cn } from '../lib/cn'
import { IconButton } from '../IconButton'
import { Tooltip } from '../Tooltip'

type Props = {
  /**
   * Drop the panel entirely below this width. For a pane that is a WIDE-SCREEN
   * affordance and nothing else: a table of contents wrapped under the article
   * on a phone points only at things already scrolled past, which the page
   * audit reads as a dead column (2026-08-26). Same word and same two steps as
   * `<Th hideBelow>`.
   */
  hideBelow?: 'sm' | 'md'
  /** Panel heading. */
  title: ReactNode
  /** Shows a close button in the header when provided. */
  onClose?: () => void
  /** Controls in the header, before the close button (e.g. a collapse toggle). */
  headerActions?: ReactNode
  /** Pinned footer (e.g. Submit / Cancel actions). */
  footer?: ReactNode
  children: ReactNode
  id?: string
  className?: string
  /** Region label; defaults to `title` when it is a plain string. */
  label?: string
}

/* Reusable side-panel chrome: header (title + optional close) over a scrolling
 * body, with an optional pinned footer. The container's width/borders/radius are
 * left to the consumer via `className`. Used by ContentSidePanel and form panels. 
   *
   * Copy: the title names what the panel holds, in the same words the reader used
   * to open it.
   */
export function SidePanel({ title, onClose, headerActions, footer, children, id, className, label, hideBelow }: Props) {
  const { t } = useTranslation()
  return (
    <section
      id={id}
      className={cn('side-panel', className)} data-raised="card"
      data-hide-below={hideBelow}
      aria-label={label ?? (typeof title === 'string' ? title : undefined)}
    >
      <header className="side-panel-header">
        <h2 className="side-panel-title">{title}</h2>
        {headerActions && <div className="side-panel-actions">{headerActions}</div>}
        {onClose && (
          <Tooltip content={t('a11y.close')}>
            <IconButton icon="close" size="md" aria-label={t('a11y.close')} onClick={onClose} />
          </Tooltip>
        )}
      </header>
      {/* The body scrolls, so it is a tab stop: a region a mouse can scroll and a keyboard cannot
        * reach is content that exists only for some people (axe: scrollable-region-focusable).
        * jsx-a11y cannot tell that this div scrolls and asks for an interactive role, which would
        * be a lie; the panel's own <section aria-label> already names the region. */}
      {/* eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex */}
      <div className="side-panel-body" tabIndex={0}>{children}</div>
      {footer && <footer className="side-panel-footer">{footer}</footer>}
    </section>
  )
}
